import raw from './index.json';
import type { FullProblem, Problem, ProblemDetail, TestCase } from '../types';

/** Generated by `python3 data/build.py`, already in roadmap order: topic by topic, easy to hard, must-know first. */
export const PROBLEMS = raw as unknown as Problem[];

export const BY_ID: ReadonlyMap<string, Problem> = new Map(PROBLEMS.map((p) => [p.id, p]));

/** Topics in roadmap order (the order of their first problem). */
export const TOPICS: string[] = Array.from(new Set(PROBLEMS.map((p) => p.topic)));

const testFiles = import.meta.glob<TestCase[]>('./tests/*.json', { import: 'default' });
const detailFiles = import.meta.glob<ProblemDetail>('./details/*.json', { import: 'default' });

function lazy<T>(files: Record<string, () => Promise<T>>, dir: string, what: string) {
  const cache = new Map<string, Promise<T>>();
  return (id: string): Promise<T> => {
    let hit = cache.get(id);
    if (!hit) {
      const loader = files[`./${dir}/${id}.json`];
      hit = loader ? loader() : Promise.reject(new Error(`No ${what} for ${id}`));
      hit.catch(() => cache.delete(id));
      cache.set(id, hit);
    }
    return hit;
  };
}

/** All test cases of a problem (including hidden and large ones). Each set loads once, on demand. */
export const loadTests = lazy(testFiles, 'tests', 'test data');

/** Statement, hints, editorial and reference solution of one problem. */
export const loadDetail = lazy(detailFiles, 'details', 'problem text');

export async function loadFull(p: Problem): Promise<FullProblem> {
  return { ...p, ...(await loadDetail(p.id)) };
}
